export default "import {\n  SceneFlexLayout,\n  SceneTimeRange,\n  SceneVariableSet,\n  TestVariable,\n  EmbeddedScene,\n  SceneFlexItem,\n  SceneAppPage,\n  SceneAppPageState,\n  PanelBuilders,\n  VariableValueSelectors,\n  SceneByVariableRepeater,\n  VariableValueOption,\n} from '@grafana/scenes';\nimport { getQueryRunnerWithRandomWalkQuery } from './utils';\n\nexport function getVariableRepeaterDemo(defaults: SceneAppPageState) {\n  return new SceneAppPage({\n    ...defaults,\n    $timeRange: new SceneTimeRange(),\n    getScene: () => {\n      return new EmbeddedScene({\n        controls: [new VariableValueSelectors({})],\n        $variables: new SceneVariableSet({\n          variables: [\n            new TestVariable({\n              name: 'server',\n              query: 'A.*',\n              value: 'server',\n              text: '',\n              description: 'Server name',\n              delayMs: 1000,\n              includeAll: true,\n              defaultToAll: true,\n              isMulti: true,\n              options: [],\n            }),\n          ],\n        }),\n        body: new SceneByVariableRepeater({\n          variableName: 'server',\n          body: new SceneFlexLayout({\n            direction: 'column',\n            children: [],\n          }),\n          getLayoutChild: (option) => getGraphAndTextPanel(option),\n        }),\n      });\n    },\n  });\n}\n\nfunction getGraphAndTextPanel(option: VariableValueOption) {\n  return new SceneFlexLayout({\n    minHeight: 200,\n    children: [\n      new SceneFlexItem({\n        body: PanelBuilders.timeseries()\n          .setTitle(`server: ${option.value}`)\n          .setData(\n            getQueryRunnerWithRandomWalkQuery({\n              alias: `server: ${option.value}`,\n            })\n          )\n          .build(),\n      }),\n      new SceneFlexItem({\n        body: PanelBuilders.stat().setTitle('Max').setData(getQueryRunnerWithRandomWalkQuery({})).build(),\n      }),\n    ],\n  });\n}\n";